import os
import torch


class Config:
    """
    Global configuration for the Ventilator Pressure Prediction task.
    Implements settings for the PCDRH-Net strategy.
    """

    # ==========================
    # File Paths & Directories
    # ==========================
    # Input Metadata (Generated by metadata script)
    METADATA_DIR = "./metadata"
    TRAIN_PATH = os.path.join(METADATA_DIR, "train.csv")
    VAL_PATH = os.path.join(METADATA_DIR, "validation.csv")
    TEST_PATH = os.path.join(METADATA_DIR, "test.csv")

    # Working Directory for Caching (Idea 29 specific)
    CACHE_DIR = "./working/idea_29/"

    # Submission Output
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # ==========================
    # Reproducibility
    # ==========================
    SEED = 42

    # ==========================
    # Data Processing
    # ==========================
    # Debugging flag to use a smaller subset of data
    DEBUG = False
    DEBUG_SAMPLE_SIZE = 5000  # Number of breaths to load in debug mode

    # ==========================
    # Training Hyperparameters
    # ==========================
    BATCH_SIZE = 128
    EPOCHS = 80

    # Optimization
    LEARNING_RATE = 1e-3
    WEIGHT_DECAY = 1e-4
    MAX_GRAD_NORM = 1.0

    # Scheduler (ReduceLROnPlateau)
    SCHEDULER_FACTOR = 0.5
    SCHEDULER_PATIENCE = 5
    SCHEDULER_MIN_LR = 1e-6

    # Early Stopping
    EARLY_STOPPING_PATIENCE = 15

    # ==========================
    # Model Architecture (PCDRH-Net)
    # ==========================
    # Branch 1: Deep Residual Dense TCN (Resistive Stream)
    # Progressive channel scaling for deep feature extraction
    CNN_FILTERS = [64, 128, 256, 512]
    CNN_KERNEL_SIZE = 9
    CNN_DROPOUT = 0.1

    # Branch 2: High-Capacity Bidirectional LSTM (Elastic Stream)
    LSTM_HIDDEN_SIZE = 512
    LSTM_LAYERS = 3
    LSTM_BIDIRECTIONAL = True

    # Fusion Head
    DENSE_HIDDEN_SIZE = 1024

    # ==========================
    # Feature Engineering
    # ==========================
    # Stream A: Model Features (Scaled)
    # These features are processed with RobustScaler and fed into the model backbone.
    # Includes raw controls, lung attributes, kinematics, and explicit physical terms.
    STREAM_A_COLS = [
        "u_in",  # Control input (Inspiratory valve)
        "u_out",  # Control input (Expiratory valve - for completeness)
        "R",  # Lung Resistance
        "C",  # Lung Compliance
        "u_in_diff1",  # Backward Velocity: u_in(t) - u_in(t-1)
        "u_in_lead1",  # Forward Lookahead t+1
        "u_in_lead2",  # Forward Lookahead t+2
        "u_in_lead3",  # Forward Lookahead t+3
        "u_in_lead4",  # Forward Lookahead t+4
        "area",  # Numerical Integration of Volume (sum(u_in * dt))
        "time_delta",  # Explicit Time-Delta (dt)
        "area_C",  # Explicit Physics Interaction: Area / C
    ]

    # Stream B: Logic/Mask Features (Raw)
    # These features are NOT scaled and are used specifically for the Logic-Gated Loss function.
    STREAM_B_COLS = ["u_out"]  # Binary expiratory valve status

    # Target Variable
    TARGET_COL = "pressure"

    # Identification Columns
    ID_COL = "id"
    BREATH_ID_COL = "breath_id"

    # ==========================
    # Hardware
    # ==========================
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    NUM_WORKERS = 4

    @classmethod
    def setup(cls):
        """
        Initialize the environment by creating necessary directories.
        """
        os.makedirs(cls.CACHE_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)
